#include <cstring>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Token-based authentication service with session management
// Handles variable-length tokens with a length-prefix protocol

static const int MAX_SESSIONS = 64;
static const int TOKEN_STORE_SIZE = 256;

struct Session {
    int fd;
    bool authenticated;
    char username[32];
    char token_store[TOKEN_STORE_SIZE];
    int token_count;
    void (*on_auth_success)(Session*);
    void (*on_auth_failure)(Session*);
};

static Session sessions[MAX_SESSIONS];

void default_auth_success(Session* s) {
    const char* msg = "AUTH_OK\n";
    write(s->fd, msg, strlen(msg));
}

void default_auth_failure(Session* s) {
    const char* msg = "AUTH_FAIL\n";
    write(s->fd, msg, strlen(msg));
}

void init_session(Session* s, int fd) {
    memset(s, 0, sizeof(Session));
    s->fd = fd;
    s->authenticated = false;
    s->token_count = 0;
    s->on_auth_success = default_auth_success;
    s->on_auth_failure = default_auth_failure;
}

// Protocol: [1 byte cmd][2 bytes payload_len (big-endian)][payload]
// Commands:
//   0x01 = STORE_TOKEN: stores a token in token_store
//   0x02 = AUTH: authenticate with stored tokens
//   0x03 = RESET: clear token store

// Parse a 16-bit big-endian length from buffer
int16_t parse_length(const unsigned char* buf) {
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Store tokens incrementally into the session's token_store
// Each token is stored as [1-byte len][token_data]
// Returns bytes consumed from token_store
int store_token(Session* s, const unsigned char* token_data, int16_t token_len) {
    // Calculate current position in token_store
    int pos = 0;
    for (int i = 0; i < s->token_count; i++) {
        int entry_len = (unsigned char)s->token_store[pos];
        pos += 1 + entry_len;
    }

    // Bounds check: ensure we don't write past token_store
    // token_len is int16_t, so this comparison is signed
    if (pos + 1 + token_len > TOKEN_STORE_SIZE) {
        return -1;
    }

    // Store length prefix and token data
    s->token_store[pos] = (char)token_len;
    memcpy(&s->token_store[pos + 1], token_data, (size_t)(uint16_t)token_len);
    s->token_count++;

    return pos + 1 + token_len;
}

bool verify_tokens(Session* s) {
    // Simple verification: check if we have at least 2 tokens
    // and first token matches a known pattern
    if (s->token_count < 2) return false;
    if (s->token_store[1] == 'A' && s->token_store[2] == 'D') return true;
    return false;
}

void handle_client(int client_fd) {
    Session* s = nullptr;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].fd == 0) {
            s = &sessions[i];
            init_session(s, client_fd);
            break;
        }
    }
    if (!s) { close(client_fd); return; }

    unsigned char header[3];
    while (true) {
        // Read command header
        ssize_t n = read(client_fd, header, 3);
        if (n <= 0) break;
        if (n < 3) break;

        uint8_t cmd = header[0];
        int16_t payload_len = parse_length(&header[1]);

        // Validate payload length - reject negative or oversized
        if (payload_len < 0 || payload_len > 1024) {
            break;
        }

        unsigned char payload[1024];
        if (payload_len > 0) {
            ssize_t total = 0;
            while (total < payload_len) {
                ssize_t r = read(client_fd, payload + total, payload_len - total);
                if (r <= 0) goto cleanup;
                total += r;
            }
        }

        switch (cmd) {
            case 0x01: { // STORE_TOKEN
                // The token_data within payload is: [1-byte token_len][token_bytes]
                if (payload_len < 1) break;
                int16_t token_len = (int16_t)(int8_t)payload[0]; // sign-extended from byte
                const unsigned char* token_data = &payload[1];

                if (token_len <= 0) break; // reject zero/negative token length

                int result = store_token(s, token_data, token_len);
                if (result < 0) {
                    const char* msg = "STORE_FULL\n";
                    write(client_fd, msg, strlen(msg));
                } else {
                    const char* msg = "STORED\n";
                    write(client_fd, msg, strlen(msg));
                }
                break;
            }
            case 0x02: { // AUTH
                if (verify_tokens(s)) {
                    s->authenticated = true;
                    s->on_auth_success(s);
                } else {
                    s->on_auth_failure(s);
                }
                break;
            }
            case 0x03: { // RESET
                memset(s->token_store, 0, TOKEN_STORE_SIZE);
                s->token_count = 0;
                const char* msg = "RESET_OK\n";
                write(client_fd, msg, strlen(msg));
                break;
            }
            default:
                break;
        }
    }

cleanup:
    s->fd = 0;
    close(client_fd);
}

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_OPTION, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(9090);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) return 1;
    if (listen(server_fd, 10) < 0) return 1;

    memset(sessions, 0, sizeof(sessions));

    while (true) {
        int client_fd = accept(server_fd, nullptr, nullptr);
        if (client_fd < 0) continue;
        handle_client(client_fd);
    }

    return 0;
}
